import{_ as e,c as s,o as t,b0 as l}from"./chunks/framework.Dmsv_Tiv.js";const o="/media-docs/assets/image-20251217163712976.C8paVW0Z.png",c="/media-docs/assets/image-20251217164015079.Bc3It7Qf.png",n="/media-docs/assets/image-20251217164538559.BcaYJ4CM.png",h=JSON.parse('{"title":"LV090-MP4工程实践","description":null,"frontmatter":{"title":"LV090-MP4工程实践","date":"2025-12-17T16:23:02.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/container/126b1a9af03e1ea424fa679a","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-17T16:23:02.490Z","fulluuid":"424fa679a21b421b8f2c8566598fb631","useduuid":"424fa679a"}},"headers":[],"relativePath":"sdoc/vcodec/container/126b1a9af03e1ea424fa679a.md","filePath":"sdoc/20-视频编解码/15-封装/LV090-MP4工程实践.md","lastUpdated":1767537778000}'),p={name:"sdoc/vcodec/container/126b1a9af03e1ea424fa679a.md"};function m(i,a,r,d,_,u){return t(),s("div",null,[...a[0]||(a[0]=[l('<h1 id="lv090-mp4工程实践" tabindex="-1">LV090-MP4工程实践 <a class="header-anchor" href="#lv090-mp4工程实践" aria-label="Permalink to &quot;LV090-MP4工程实践&quot;">​</a></h1><h2 id="一、工程实践" tabindex="-1">一、工程实践 <a class="header-anchor" href="#一、工程实践" aria-label="Permalink to &quot;一、工程实践&quot;">​</a></h2><p>接下来我们结合一个工程问题来实践一下。我们如何计算每一个 sample 在文件中的具体位置，判断它是不是关键帧，并计算它的具体时间。</p><p>计算 sample 的具体位置需要使用 stco（或 co64）、stsc 和 stsz。我们首先通过 stsc 将每一个 sample 属于哪一个 chunk 计算出来。这样每一个 chunk 的第一个 sample 就知道是哪个了。然后我们通过 stco 和 co64 就可以知道对应序号的 chunk 的第一个 sample 在文件中的地址了。我们再通过 stsz 查询每个 sample 的大小，从 chunk 的第一个 sample 的地址将中间的 sample 的大小一个个地加上去就可以得到每一个 sample 的地址了。</p><p><img src="'+o+'" alt="image-20251217163712976"></p><p>而 sample 是不是关键帧，我们只需要通过 stss 对应每一个 sample 序号查询就可以得到。</p><p><img src="'+c+'" alt="image-20251217164015079"></p><p>计算 sample 的时间我们需要用到 stts 和 ctts。我们先通过 stts 得到每一个 sample 的时长，第 n 个 sample 的结束时间就是第 n-1 个 sample 的结束时间加上第 n 个 sample 的时长。但是需要注意一下，这个是 DTS，我们还需要通过 ctts box 得到每一个 sample 的 PTS 和 DTS 的差值。最后每一个 sample 的 PTS 就是等于 DTS 加上 CTS。</p><p><img src="'+n+'" alt="image-20251217164538559"></p>',9)])])}const g=e(p,[["render",m]]);export{h as __pageData,g as default};
